    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name, metric, min(value) AS min_v, max(value) AS max_v FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'profile%' AND metric = 'k8s.container.restarts' GROUP BY 1,2",
          "claim": "The profile pod's container restart count climbed from 0 to 6 during the abnormal window, showing a crash loop."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, min(value) AS min_v, max(value) AS max_v FROM abnormal_metrics WHERE metric = 'k8s.deployment.available' AND service_name = 'profile' GROUP BY 1,2",
          "claim": "profile's deployment reports 0 available instances for the whole abnormal window, versus 1 for other services."
        },
        {
          "kind": "trace",
          "sql": "SELECT count(*) AS profile_spans_abnormal FROM abnormal_traces WHERE service_name = 'profile'",
          "claim": "profile emits no spans at all in the abnormal period, though it had about 1184 server spans normally."
        },
        {
          "kind": "log",
          "sql": "SELECT time, service_name, message FROM abnormal_logs WHERE message LIKE '%hotel-reserv-profile definition changed%' LIMIT 5",
          "claim": "A kubelet event shows the hotel-reserv-profile container definition changed and was killed and restarted."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name = 'frontend' AND span_name IN ('profile.Profile/GetProfiles', 'HTTP /hotels', 'HTTP /recommendations') GROUP BY 1,2,3 ORDER BY 1,2,3",
          "claim": "Frontend's GetProfiles client calls fail near-instantly, and the /hotels and /recommendations HTTP requests return 500."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) AS n FROM abnormal_logs WHERE service_name = 'frontend' AND level = 'ERROR' GROUP BY 1,2,3",
          "claim": "Frontend logs about 607 ERROR entries reading 'Get profiles failed' in the abnormal window, versus none normally."
        }
      ]
    }
  ]
}
